import os, re, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
OUT = 'storage/noesis/nmap/inquire_v4'

# Canonicalization for boundary labels
CANON = {
  'xl':'xL','x_l':'xL','xleft':'xL','left':'xL','xmin':'xL','x_min':'xL',
  'xr':'xR','x_r':'xR','xright':'xR','right':'xR','xmax':'xR','x_max':'xR',
  'yb':'yB','y_b':'yB','ybottom':'yB','bottom':'yB','ymin':'yB','y_min':'yB',
  'yt':'yT','y_t':'yT','ytop':'yT','top':'yT','ymax':'yT','y_max':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}
INT_RE = re.compile(r'[-+]?\d+')
NUM_RE = re.compile(r'[-+]?\d+(?:\.\d+)?', re.I)
SIDE_RE = re.compile(r'(xL|xR|yB|yT|xl|xr|yb|yt|left|right|top|bottom|xmin|xmax|ymin|ymax|x_min|x_max|y_min|y_max)', re.I)

def read_lines(path):
    with open(path, 'r', encoding='utf-8', errors='ignore') as f:
        return f.read().strip().splitlines()

def parse_pairs_raw(path):
    rows=[]
    if not path or not os.path.exists(path): return rows
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
                rows.append((i, j))
            except Exception:
                continue
    return rows

def parse_boundary_raw(path):
    rows=[]
    if not path or not os.path.exists(path): return rows
    for ln in read_lines(path):
        itoks = INT_RE.findall(ln)
        if not itoks:
            continue
        try:
            i = int(itoks[0])
        except Exception:
            continue
        m = SIDE_RE.search(ln)
        if not m: 
            continue
        s_raw = m.group(1)
        k = s_raw.replace(' ', '').replace(':','').replace(',','').replace('.','').lower()
        s = CANON.get(k, CANON.get(k.lower(), k))
        if s in ('xL','xR','yB','yT'):
            rows.append((i, s))
    return rows

def normalize_indices(rows, kind):
    if kind == 'pairs':
        idxs = [i for (i, _) in rows] + [j for (_, j) in rows]
    else:
        idxs = [i for (i, _) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}
    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N for v in idxs)
    out = set(); meta = {'applied': False, 'mode': 'as-is'}
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind == 'pairs':
            for (i, j) in rows:
                a, b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a != b:
                    u, v = (a, b) if a < b else (b, a); out.add((u, v))
        else:
            for (i, s) in rows:
                a = i-1
                if 0 <= a < N: out.add((a, s))
    else:
        if kind == 'pairs':
            for (i, j) in rows:
                if 0 <= i < N and 0 <= j < N and i != j:
                    u, v = (i, j) if i < j else (j, i); out.add((u, v))
        else:
            for (i, s) in rows:
                if 0 <= i < N: out.add((i, s))
    return out, meta

def read_centers(path):
    if not path or not os.path.exists(path): return None
    rows=[]
    for ln in read_lines(path):
        toks = NUM_RE.findall(ln)
        if len(toks) >= 2:
            rows.append([float(toks[0]), float(toks[1])])
    C = np.array(rows, float)
    return C if C.shape == (N, 2) else None

def find_inquire_root():
    # Prefer exact path, fallback to lowercase
    for p in ['storage/Inquire/nmap/n26', 'storage/inquire/nmap/n26']:
        if os.path.exists(p): return p
    return None

def find_file(dir_root, kind, base=None):
    """
    kind: 'boundary'|'pairs' for SOTA files, or base-prefixed Nudged files.
    Supports tol tag variants including tol1e08, tol1e8, tol1e-8, tol1e-08.
    """
    if not dir_root or not os.path.exists(dir_root): return None
    candidates=[]
    if base is None:
        names = [
            'active_boundary_tol1e08.csv','active_pairs_tol1e08.csv',
            'active_boundary_tol1e8.csv', 'active_pairs_tol1e8.csv',
            'active_boundary_tol1e-8.csv','active_pairs_tol1e-8.csv',
            'active_boundary_tol1e-08.csv','active_pairs_tol1e-08.csv',
            'active_boundary.csv','active_pairs.csv'
        ]
        for fn in names:
            fp = os.path.join(dir_root, fn)
            if os.path.exists(fp):
                candidates.append(fp)
    else:
        # Nudged_* base
        tag_variants = ['tol1e08','tol1e8','tol1e-8','tol1e-08']
        for tv in tag_variants:
            fn = f'{base}_active_{"boundary" if kind=="boundary" else "pairs"}_{tv}.csv'
            fp = os.path.join(dir_root, fn)
            if os.path.exists(fp): candidates.append(fp)
    if candidates:
        # Prefer longer (more specific) filenames
        candidates.sort(key=lambda s: (-len(os.path.basename(s)), s))
        # Return first match for requested kind
        for fp in candidates:
            fl = os.path.basename(fp).lower()
            if kind == 'boundary' and 'boundary' in fl: return fp
            if kind == 'pairs' and 'pairs' in fl: return fp
    # Last resort: scan dir for any active_* file containing the token
    for fn in os.listdir(dir_root):
        fl = fn.lower()
        if fl.endswith('.csv') and 'active' in fl and kind in fl:
            return os.path.join(dir_root, fn)
    return None

def load_pack(dir_root, base=None):
    if base is None:
        b = find_file(dir_root, 'boundary')
        p = find_file(dir_root, 'pairs')
        centers = read_centers(os.path.join(dir_root, 'centers.txt'))  # may be None
    else:
        b = find_file(dir_root, 'boundary', base=base)
        p = find_file(dir_root, 'pairs',    base=base)
        centers = read_centers(os.path.join(dir_root, f'{base}_centers.txt'))
    pairs_raw = parse_pairs_raw(p); bound_raw = parse_boundary_raw(b)
    pairs, _ = normalize_indices(pairs_raw, 'pairs')
    bound, _ = normalize_indices(bound_raw, 'bound')
    return {'pairs': pairs, 'bound': bound, 'centers': centers, 'meta': {'b_path': b, 'p_path': p}}

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return {'j': J, 'I': len(I), 'U': len(U)}

def align_map(CA, CB):
    if CA is None or CB is None: return None
    M = np.sum((CA[:, None, :] - CB[None, :, :])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx = np.lexsort((CA[:,1], CA[:,0])); b_idx = np.lexsort((CB[:,1], CB[:,0]))
        P = np.zeros(N, dtype=int); P[a_idx] = b_idx; return P
    r, c = linear_sum_assignment(M)
    P = np.zeros(N, dtype=int); P[r] = c
    return P

def map_pairs(P, S):
    if P is None: return None
    T = set()
    for (i, j) in S:
        a, b = int(P[i]), int(P[j])
        if a == b: continue
        u, v = (a, b) if a < b else (b, a)
        T.add((u, v))
    return T

def map_bound(P, S):
    if P is None: return None
    return set((int(P[i]), s) for (i, s) in S)

def write_json_csv(base, tag, res):
    os.makedirs(base, exist_ok=True)
    with open(os.path.join(base, f'{tag}.json'), 'w') as f:
        json.dump(res, f, indent=2, sort_keys=True)
    with open(os.path.join(base, f'{tag}.csv'), 'w', newline='') as f:
        w = csv.writer(f); w.writerow(['n','boundary_j','I_b','U_b','pairs_j','I_p','U_p'])
        w.writerow([N, res['boundary']['j'], res['boundary']['I'], res['boundary']['U'],
                       res['pairs']['j'],    res['pairs']['I'],    res['pairs']['U']])

def compare_two(A, B, out_base, tag):
    res = {'n': N, 'boundary': jaccard(A['bound'], B['bound']), 'pairs': jaccard(A['pairs'], B['pairs']), 'note':'unaligned'}
    write_json_csv(out_base, f'{tag}', res)
    P = align_map(A['centers'], B['centers'])
    if P is not None:
        Ab, Ap = map_bound(P, A['bound']), map_pairs(P, A['pairs'])
        if Ab is not None and Ap is not None:
            res2 = {'n': N, 'alignment': 'hungarian', 'boundary': jaccard(Ab, B['bound']), 'pairs': jaccard(Ap, B['pairs'])}
            write_json_csv(out_base, f'{tag}_aligned', res2)

def consensus_sets(packs):
    Bs = [packs[k]['bound'] for k in packs]; Ps = [packs[k]['pairs'] for k in packs]
    inter_b = set.intersection(*Bs) if all(isinstance(s,set) for s in Bs) else set()
    union_b = set.union(*Bs) if all(isinstance(s,set) for s in Bs) else set()
    inter_p = set.intersection(*Ps) if all(isinstance(s,set) for s in Ps) else set()
    union_p = set.union(*Ps) if all(isinstance(s,set) for s in Ps) else set()
    sizes_b = {k: len(packs[k]['bound']) for k in packs}
    sizes_p = {k: len(packs[k]['pairs']) for k in packs}
    return {'boundary': {'intersection': len(inter_b), 'union': len(union_b), 'sizes': sizes_b},
            'pairs':    {'intersection': len(inter_p), 'union': len(union_p), 'sizes': sizes_p}}

def construct_packing():
    os.makedirs(OUT, exist_ok=True)
    root_inq = find_inquire_root()
    # Load SOTA packs (sets + centers where available)
    noe = {'pairs': set(), 'bound': set(), 'centers': read_centers('storage/noesis/latest_centers.txt')}
    # Noesis sets from our exports dir
    def load_sets_from_dir(d):
        # Try standard names; fallback scan
        b = None; p = None
        if os.path.exists(d):
            for fn in os.listdir(d):
                fl = fn.lower()
                if fl.endswith('.csv') and 'active' in fl and 'boundary' in fl and b is None: b = os.path.join(d, fn)
                if fl.endswith('.csv') and 'active' in fl and 'pairs' in fl and p is None:    p = os.path.join(d, fn)
        pr = parse_pairs_raw(p); bd = parse_boundary_raw(b)
        P,_ = normalize_indices(pr, 'pairs'); B,_ = normalize_indices(bd, 'bound')
        return P, B
    P_noe, B_noe = load_sets_from_dir('storage/noesis/exports/sota_243'); noe['pairs']=P_noe; noe['bound']=B_noe

    sci = load_pack('storage/Scientia/nmap/n26')  # has sets + centers
    pro = load_pack('storage/Prometheus/nmap/n26')
    inq_sota = load_pack(root_inq) if root_inq else {'pairs': set(), 'bound': set(), 'centers': None}

    # 4-lineage consensus (SOTAs)
    sotapacks = {'Noesis_243': noe, 'Scientia_259': sci, 'Prometheus_298': pro, 'Inquire_207': inq_sota}
    cons4 = consensus_sets(sotapacks)
    with open(os.path.join(OUT, 'consensus_4lineage_sotas_tol1e8.json'), 'w') as f:
        json.dump({'n':N, 'ids': list(sotapacks.keys()), **cons4}, f, indent=2, sort_keys=True)

    # Pairwise matrix among SOTAs (unaligned, sets)
    with open(os.path.join(OUT, 'jaccard_matrix_sotas_tol1e8.csv'),'w',newline='') as f:
        w=csv.writer(f); w.writerow(['A','B','boundary_j','I_b','U_b','pairs_j','I_p','U_p'])
        keys = list(sotapacks.keys())
        pairs = [('Noesis_243','Scientia_259'),('Noesis_243','Prometheus_298'),('Noesis_243','Inquire_207'),
                 ('Scientia_259','Prometheus_298'),('Scientia_259','Inquire_207'),('Prometheus_298','Inquire_207')]
        for a,b in pairs:
            A=sotapacks[a]; B=sotapacks[b]
            jb=jaccard(A['bound'],B['bound']); jp=jaccard(A['pairs'],B['pairs'])
            w.writerow([a,b,jb['j'],jb['I'],jb['U'],jp['j'],jp['I'],jp['U']])

    # Per-pack (Nudged_*) analyses if present
    if root_inq and os.path.exists(root_inq):
        nudged = []
        for fn in os.listdir(root_inq):
            if fn.startswith('Nudged_') and fn.endswith('_centers.txt'):
                base = fn[:-len('_centers.txt')]
                nudged.append(base)
        summary=[]
        for base in sorted(set(nudged)):
            pack = load_pack(root_inq, base=base)
            out_dir = os.path.join(OUT, base); os.makedirs(out_dir, exist_ok=True)
            compare_two(pack, noe, out_dir, f'{base}_vs_noesis243_tol1e8')
            compare_two(pack, sci, out_dir, f'{base}_vs_scientia259_tol1e8')
            compare_two(pack, pro, out_dir, f'{base}_vs_prometheus298_tol1e8')
            compare_two(pack, inq_sota, out_dir, f'{base}_vs_inquire207_tol1e8')
            # Summary line: boundary J vs each reference (prefer aligned if exists)
            def loadJ(pathA, pathB):
                if os.path.exists(pathA):
                    with open(pathA,'r') as f: return float(json.load(f)['boundary']['j'])
                with open(pathB,'r') as f: return float(json.load(f)['boundary']['j'])
            def JJ(tag):
                return loadJ(os.path.join(out_dir,f'{base}_vs_{tag}_tol1e8_aligned.json'),
                             os.path.join(out_dir,f'{base}_vs_{tag}_tol1e8.json'))
            summary.append([base, JJ('noesis243'), JJ('scientia259'), JJ('prometheus298'), JJ('inquire207')])
        if summary:
            with open(os.path.join(OUT,'inquire_v4_summary.csv'),'w',newline='') as f:
                w=csv.writer(f); w.writerow(['pack','Jb_noesis243','Jb_scientia259','Jb_prometheus298','Jb_inquire207'])
                for row in summary: w.writerow(row)

    # Return current Noesis packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt'); r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c,float).reshape(N,2), np.array(r,float).reshape(N,)
